// Generated by AI (UnitTest MCP)
//! Ingest a git commit as an `intent` node linked to the artifacts it touched.

use crate::error::{MindLeakError, Result};
use crate::graph::GraphStore;
use crate::ingest::{clamp, is_ignored_path, repo_relative, short_hash};
use crate::model::{Edge, Node, NodeType, RelationType};

/// A commit captured from git telemetry.
#[derive(Debug, Clone)]
pub struct CommitRecord {
    pub sha: Option<String>,
    pub message: String,
    pub changed_files: Vec<String>,
    pub timestamp: i64,
}

/// Extract any explicit decision/rationale markers from a commit message or
/// inline comment (`DECISION:`, `HACK:`, `WHY:`, `NOTE:`).
pub fn extract_rationale(message: &str) -> Vec<String> {
    let mut out = Vec::new();
    for line in message.lines() {
        let trimmed = line
            .trim()
            .trim_start_matches("//")
            .trim_start_matches('#')
            .trim();
        for marker in ["DECISION:", "HACK:", "WHY:", "NOTE:", "FIXME:"] {
            if let Some(idx) = trimmed.to_ascii_uppercase().find(marker) {
                let rest = trimmed[idx + marker.len()..].trim();
                if !rest.is_empty() {
                    out.push(format!("{marker} {rest}"));
                }
            }
        }
    }
    out
}

/// A full commit hash: 40 hex characters for SHA-1, 64 for SHA-256.
///
/// Anything shorter is an abbreviation, and an abbreviation cannot be expanded
/// here — ingestion is deterministic and never shells out to git (invariant 1).
fn is_full_commit_sha(sha: &str) -> bool {
    matches!(sha.len(), 40 | 64) && sha.chars().all(|c| c.is_ascii_hexdigit())
}

/// Ingest one commit. Creates an intent node and `refactored` edges to files.
///
/// `root` is the checkout this process serves; changed files inside it become
/// repo-relative so every worktree writes the same node ids (ADR-0038).
///
/// The node id is derived from the commit hash, so the hash must identify the
/// commit exactly: an abbreviation is refused rather than accepted, because
/// `intent:007835a` and `intent:007835a1c979...` are two nodes competing to
/// represent one event, and nothing downstream can tell they are the same
/// commit. Case is normalised for the same reason.
pub fn ingest_commit(
    store: &GraphStore,
    rec: &CommitRecord,
    now: i64,
    root: Option<&str>,
) -> Result<crate::graph::WriteOutcome> {
    let key = match rec.sha.as_deref() {
        Some(sha) => {
            let sha = sha.trim();
            if !is_full_commit_sha(sha) {
                return Err(MindLeakError::InvalidArgument(format!(
                    "sha {sha:?} is not a full commit hash; pass all 40 (or 64) \
                     hex characters, because an abbreviation would create a \
                     second intent node for a commit already ingested under its \
                     full hash"
                )));
            }
            sha.to_ascii_lowercase()
        }
        None => short_hash(&format!("{}|{}", rec.message, rec.timestamp)),
    };
    let intent_id = format!("intent:{key}");
    let first_line = rec.message.lines().next().unwrap_or("").trim();
    let label = clamp(first_line, 80);

    let mut content = rec.message.clone();
    let rationale = extract_rationale(&rec.message);
    if !rationale.is_empty() {
        content.push_str("\n---\n");
        content.push_str(&rationale.join("\n"));
    }

    let intent =
        Node::new(&intent_id, NodeType::Intent, label, rec.timestamp).with_content(content);
    let mut nodes = vec![intent];
    let mut edges = Vec::new();

    let mut changed_files: Vec<String> = rec
        .changed_files
        .iter()
        .map(|file| repo_relative(file, root))
        .collect();
    changed_files.sort();
    changed_files.dedup();
    for path in changed_files {
        if is_ignored_path(&path) {
            continue;
        }
        let art_id = format!("artifact:{path}");
        let art = Node::new(&art_id, NodeType::Artifact, path.clone(), now);
        nodes.push(art);
        edges.push(Edge::new(
            &intent_id,
            &art_id,
            RelationType::Refactored,
            rec.timestamp,
        ));
    }

    let mut outcome = store.upsert_facts(&nodes, &edges)?;
    outcome.node_ids.push(intent_id);
    Ok(outcome)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A real 40-character SHA-1 commit hash.
    const FULL_SHA: &str = "007835a1c979d32371a323bb897a6d6f982fb570";

    #[test]
    fn pulls_decision_markers() {
        let msg = "Fix login\n\n// DECISION: use SQLite over Neo4j for footprint";
        let r = extract_rationale(msg);
        assert!(r.iter().any(|l| l.contains("SQLite over Neo4j")));
    }

    #[test]
    fn commit_edges_use_the_authoritative_record_timestamp() {
        let store = GraphStore::new(crate::db::open_in_memory().unwrap());
        let record = CommitRecord {
            sha: Some(FULL_SHA.to_string()),
            message: "fix: stable".to_string(),
            changed_files: vec!["src/lib.rs".to_string()],
            timestamp: 123,
        };
        ingest_commit(&store, &record, 999, None).unwrap();

        let graph = store
            .traverse(
                &[format!("intent:{FULL_SHA}")],
                crate::graph::Direction::Outgoing,
                1,
                0.0,
                123,
            )
            .unwrap();
        assert_eq!(graph.edges[0].updated_at, 123);
    }

    // Regression: one commit was splitting into two intent nodes.
    //
    // What went wrong: the node id was built from the sha exactly as supplied,
    // so ingesting a commit by its abbreviation after it had already been
    // ingested by its full hash created a *second* node. Observed on
    // 2026-07-29: an evidence bundle carried both `intent:007835a` and
    // `intent:007835a1c979...` for one commit, with duplicated `refactored`
    // edges to all four artefacts and a commit count of 2.
    //
    // Impact: inflated commit counts in conformance evidence, duplicated
    // provenance, and two nodes competing to represent one event, with nothing
    // downstream able to tell they are the same commit.
    //
    // The fix: an abbreviation is refused. It cannot be expanded here, because
    // ingestion is deterministic and never shells out to git.
    #[test]
    fn an_abbreviated_sha_is_refused_rather_than_creating_a_second_node() {
        let store = GraphStore::new(crate::db::open_in_memory().unwrap());
        let full = CommitRecord {
            sha: Some(FULL_SHA.to_string()),
            message: "fix: real work".to_string(),
            changed_files: vec!["src/lib.rs".to_string()],
            timestamp: 100,
        };
        ingest_commit(&store, &full, 100, None).unwrap();

        let abbreviated = CommitRecord {
            sha: Some(FULL_SHA[..7].to_string()),
            ..full.clone()
        };
        let error = ingest_commit(&store, &abbreviated, 100, None)
            .expect_err("an abbreviated sha must be refused, not silently forked");

        assert!(
            matches!(error, MindLeakError::InvalidArgument(_)),
            "expected a typed invalid-argument error, got {error:?}"
        );
        let message = error.to_string();
        assert!(
            message.contains("full commit hash"),
            "the error must name the fix: {message}"
        );

        // The graph still holds exactly one node for the commit.
        assert!(store
            .get_node(&format!("intent:{FULL_SHA}"))
            .unwrap()
            .is_some());
        assert!(store
            .get_node(&format!("intent:{}", &FULL_SHA[..7]))
            .unwrap()
            .is_none());
    }

    // The same identity split, reached by a different route: git prints hashes
    // lowercase, but a caller echoing a hash back in upper case would otherwise
    // mint a parallel node for the same commit.
    #[test]
    fn sha_case_does_not_fork_the_commit_into_two_nodes() {
        let store = GraphStore::new(crate::db::open_in_memory().unwrap());
        let lower = CommitRecord {
            sha: Some(FULL_SHA.to_string()),
            message: "fix: real work".to_string(),
            changed_files: vec!["src/lib.rs".to_string()],
            timestamp: 100,
        };
        ingest_commit(&store, &lower, 100, None).unwrap();

        let upper = CommitRecord {
            sha: Some(FULL_SHA.to_ascii_uppercase()),
            ..lower.clone()
        };
        ingest_commit(&store, &upper, 100, None).unwrap();

        assert!(store
            .get_node(&format!("intent:{}", FULL_SHA.to_ascii_uppercase()))
            .unwrap()
            .is_none());
        assert!(store
            .get_node(&format!("intent:{FULL_SHA}"))
            .unwrap()
            .is_some());
    }

    // A commit with no hash at all still gets a stable content-derived id, so
    // refusing abbreviations does not make unhashed telemetry unusable.
    #[test]
    fn a_commit_without_a_sha_still_ingests() {
        let store = GraphStore::new(crate::db::open_in_memory().unwrap());
        let record = CommitRecord {
            sha: None,
            message: "fix: no hash available".to_string(),
            changed_files: vec!["src/lib.rs".to_string()],
            timestamp: 100,
        };
        let outcome = ingest_commit(&store, &record, 100, None).unwrap();
        assert!(outcome.node_ids.iter().any(|id| id.starts_with("intent:")));
    }
}
